CREATE TABLE IF NOT EXISTS users(id BIGSERIAL PRIMARY KEY,full_name TEXT NOT NULL,full_name_normalized TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS games(id BIGSERIAL PRIMARY KEY,game_code TEXT NOT NULL UNIQUE,title TEXT NOT NULL,game_path TEXT NOT NULL,active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS user_game_progress(id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,game_id BIGINT NOT NULL REFERENCES games(id) ON DELETE CASCADE,started BOOLEAN NOT NULL DEFAULT FALSE,first_started_at TIMESTAMPTZ,completion_count INTEGER NOT NULL DEFAULT 0,best_seconds INTEGER,last_started_at TIMESTAMPTZ,last_completed_at TIMESTAMPTZ,updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(user_id,game_id));
CREATE TABLE IF NOT EXISTS game_sessions(id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,game_id BIGINT NOT NULL REFERENCES games(id) ON DELETE CASCADE,duration_seconds INTEGER NOT NULL CHECK(duration_seconds>=0),completed_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS idx_sessions_completed ON game_sessions(completed_at);
